{"path": "task/workspace/data/validation/string.go", "start": 1, "lines": 22, "offset": 0, "total_lines": 22, "content": "// Package validation provides validation for data inside widgets
package validation

import "fyne.io/fyne/v2"

// NewAllStrings creates a validator that requires all provided validators to pass.
// It returns the first error encountered, or nil if all validators pass.
//
// Since: 2.5
func NewAllStrings(validators ...fyne.StringValidator) fyne.StringValidator {
	return func(text string) error {
		for _, validator := range validators {
			if validator == nil {
				continue
			}
			if err := validator(text); err != nil {
				return err
			}
		}
		return nil
	}
}
